function sideOutline(sign){const s=new THREE.Shape();s.moveTo(-4.25,16);s.lineTo(-8,16);s.absarc(-8,12,4,Math.PI/2,Math.PI,false);s.lineTo(-12,-12);s.absarc(-8,-12,4,Math.PI,Math.PI*1.5,false);s.lineTo(-5,-16);s.lineTo(-5,-14.9);s.lineTo(-8,-14.9);s.absarc(-8,-12,2.9,Math.PI*1.5,Math.PI,true);s.lineTo(-10.9,12);s.absarc(-8,12,2.9,Math.PI,Math.PI/2,true);s.lineTo(-4.25,14.9);s.closePath();return sign<0?s:polygon(s.getPoints(48).map(v=>[-v.x,v.y]).reverse());}
